INSERT INTO text_works (id, title, authors, language) VALUES
    ('10000000-0000-0000-0000-000000000001', 'Красная Шапочка', 'Русская народная сказка', 'rus');
INSERT INTO voice_parts (id, text_work_id, name) VALUES
    ('10000000-0000-0000-0000-000000000100', '10000000-0000-0000-0000-000000000001', 'Рассказчик'),
    ('10000000-0000-0000-0000-000000000101', '10000000-0000-0000-0000-000000000001', 'Мама'),
    ('10000000-0000-0000-0000-000000000102', '10000000-0000-0000-0000-000000000001', 'Шапочка'),
    ('10000000-0000-0000-0000-000000000103', '10000000-0000-0000-0000-000000000001', 'Волк'),
    ('10000000-0000-0000-0000-000000000104', '10000000-0000-0000-0000-000000000001', 'Бабушка');
INSERT INTO text_work_fragments (id, text_work_id, number, voice_part_id, content) VALUES
    ('10000000-0000-0000-0000-000000001000', '10000000-0000-0000-0000-000000000001', 1, '10000000-0000-0000-0000-000000000100', 'Жила в деревне девочка, и все звали её Красной Шапочкой.'),
    ('10000000-0000-0000-0000-000000001001', '10000000-0000-0000-0000-000000000001', 2, '10000000-0000-0000-0000-000000000101', 'Отнеси бабушке пирожки, она приболела.'),
    ('10000000-0000-0000-0000-000000001002', '10000000-0000-0000-0000-000000000001', 3, '10000000-0000-0000-0000-000000000102', 'Хорошо, мама, пойду прямо по тропинке.'),
    ('10000000-0000-0000-0000-000000001003', '10000000-0000-0000-0000-000000000001', 4, '10000000-0000-0000-0000-000000000100', 'В лесу навстречу ей вышел волк.'),
    ('10000000-0000-0000-0000-000000001004', '10000000-0000-0000-0000-000000000001', 5, '10000000-0000-0000-0000-000000000103', 'Куда ты идёшь, Красная Шапочка?'),
    ('10000000-0000-0000-0000-000000001005', '10000000-0000-0000-0000-000000000001', 6, '10000000-0000-0000-0000-000000000102', 'К бабушке, несу ей пирожки.'),
    ('10000000-0000-0000-0000-000000001006', '10000000-0000-0000-0000-000000000001', 7, '10000000-0000-0000-0000-000000000103', 'А где живёт твоя бабушка?'),
    ('10000000-0000-0000-0000-000000001007', '10000000-0000-0000-0000-000000000001', 8, '10000000-0000-0000-0000-000000000102', 'За мельницей, первый дом у леса.'),
    ('10000000-0000-0000-0000-000000001008', '10000000-0000-0000-0000-000000000001', 9, '10000000-0000-0000-0000-000000000100', 'Волк побежал короткой дорогой и первым добрался до домика.'),
    ('10000000-0000-0000-0000-000000001009', '10000000-0000-0000-0000-000000000001', 10, '10000000-0000-0000-0000-000000000103', 'Внучка пришла, открывай!'),
    ('10000000-0000-0000-0000-000000001010', '10000000-0000-0000-0000-000000000001', 11, '10000000-0000-0000-0000-000000000104', 'Дёрни за верёвочку, дверь и откроется.'),
    ('10000000-0000-0000-0000-000000001011', '10000000-0000-0000-0000-000000000001', 12, '10000000-0000-0000-0000-000000000100', 'Волк запер бабушку в чулане и лёг в её постель.'),
    ('10000000-0000-0000-0000-000000001012', '10000000-0000-0000-0000-000000000001', 13, '10000000-0000-0000-0000-000000000102', 'Бабушка, почему у тебя такие большие уши?'),
    ('10000000-0000-0000-0000-000000001013', '10000000-0000-0000-0000-000000000001', 14, '10000000-0000-0000-0000-000000000103', 'Чтобы лучше тебя слышать.'),
    ('10000000-0000-0000-0000-000000001014', '10000000-0000-0000-0000-000000000001', 15, '10000000-0000-0000-0000-000000000102', 'Бабушка, почему у тебя такие большие глаза?'),
    ('10000000-0000-0000-0000-000000001015', '10000000-0000-0000-0000-000000000001', 16, '10000000-0000-0000-0000-000000000103', 'Чтобы лучше тебя видеть.'),
    ('10000000-0000-0000-0000-000000001016', '10000000-0000-0000-0000-000000000001', 17, '10000000-0000-0000-0000-000000000102', 'Бабушка, почему у тебя такие большие зубы?'),
    ('10000000-0000-0000-0000-000000001017', '10000000-0000-0000-0000-000000000001', 18, '10000000-0000-0000-0000-000000000103', 'Чтобы скорее тебя съесть!'),
    ('10000000-0000-0000-0000-000000001018', '10000000-0000-0000-0000-000000000001', 19, '10000000-0000-0000-0000-000000000100', 'На крик прибежали дровосеки и прогнали волка прочь.'),
    ('10000000-0000-0000-0000-000000001019', '10000000-0000-0000-0000-000000000001', 20, '10000000-0000-0000-0000-000000000104', 'Спасибо вам, добрые люди, что не прошли мимо.'),
    ('10000000-0000-0000-0000-000000001020', '10000000-0000-0000-0000-000000000001', 21, '10000000-0000-0000-0000-000000000102', 'Больше я с незнакомцами в лесу разговаривать не стану.');
INSERT INTO text_works (id, title, authors, language) VALUES
    ('20000000-0000-0000-0000-000000000001', 'Теремок', 'Русская народная сказка', 'rus');
INSERT INTO voice_parts (id, text_work_id, name) VALUES
    ('20000000-0000-0000-0000-000000000100', '20000000-0000-0000-0000-000000000001', 'Рассказчик'),
    ('20000000-0000-0000-0000-000000000101', '20000000-0000-0000-0000-000000000001', 'Мышка'),
    ('20000000-0000-0000-0000-000000000102', '20000000-0000-0000-0000-000000000001', 'Лягушка'),
    ('20000000-0000-0000-0000-000000000103', '20000000-0000-0000-0000-000000000001', 'Заяц'),
    ('20000000-0000-0000-0000-000000000104', '20000000-0000-0000-0000-000000000001', 'Лиса'),
    ('20000000-0000-0000-0000-000000000105', '20000000-0000-0000-0000-000000000001', 'Медведь');
INSERT INTO text_work_fragments (id, text_work_id, number, voice_part_id, content) VALUES
    ('20000000-0000-0000-0000-000000001000', '20000000-0000-0000-0000-000000000001', 1, '20000000-0000-0000-0000-000000000100', 'Стоит в поле теремок, и пока в нём никто не живёт.'),
    ('20000000-0000-0000-0000-000000001001', '20000000-0000-0000-0000-000000000001', 2, '20000000-0000-0000-0000-000000000101', 'Кто в теремочке живёт? Никого? Тогда буду жить я.'),
    ('20000000-0000-0000-0000-000000001002', '20000000-0000-0000-0000-000000000001', 3, '20000000-0000-0000-0000-000000000102', 'Кто в теремочке живёт?'),
    ('20000000-0000-0000-0000-000000001003', '20000000-0000-0000-0000-000000000001', 4, '20000000-0000-0000-0000-000000000101', 'Я, мышка-норушка. А ты кто?'),
    ('20000000-0000-0000-0000-000000001004', '20000000-0000-0000-0000-000000000001', 5, '20000000-0000-0000-0000-000000000102', 'А я лягушка-квакушка, пусти меня к себе.'),
    ('20000000-0000-0000-0000-000000001005', '20000000-0000-0000-0000-000000000001', 6, '20000000-0000-0000-0000-000000000101', 'Заходи, вдвоём веселее.'),
    ('20000000-0000-0000-0000-000000001006', '20000000-0000-0000-0000-000000000001', 7, '20000000-0000-0000-0000-000000000103', 'Кто в теремочке живёт?'),
    ('20000000-0000-0000-0000-000000001007', '20000000-0000-0000-0000-000000000001', 8, '20000000-0000-0000-0000-000000000102', 'Мышка-норушка да лягушка-квакушка. А ты кто?'),
    ('20000000-0000-0000-0000-000000001008', '20000000-0000-0000-0000-000000000001', 9, '20000000-0000-0000-0000-000000000103', 'Я зайчик-побегайчик, пустите и меня.'),
    ('20000000-0000-0000-0000-000000001009', '20000000-0000-0000-0000-000000000001', 10, '20000000-0000-0000-0000-000000000101', 'Заходи, места хватит.'),
    ('20000000-0000-0000-0000-000000001010', '20000000-0000-0000-0000-000000000001', 11, '20000000-0000-0000-0000-000000000104', 'Кто в теремочке живёт?'),
    ('20000000-0000-0000-0000-000000001011', '20000000-0000-0000-0000-000000000001', 12, '20000000-0000-0000-0000-000000000103', 'Мышка, лягушка да я, зайчик. А ты кто?'),
    ('20000000-0000-0000-0000-000000001012', '20000000-0000-0000-0000-000000000001', 13, '20000000-0000-0000-0000-000000000104', 'Я лисичка-сестричка, пустите переночевать.'),
    ('20000000-0000-0000-0000-000000001013', '20000000-0000-0000-0000-000000000001', 14, '20000000-0000-0000-0000-000000000101', 'Заходи, только не хитри.'),
    ('20000000-0000-0000-0000-000000001014', '20000000-0000-0000-0000-000000000001', 15, '20000000-0000-0000-0000-000000000105', 'Кто в теремочке живёт? Пустите и меня!'),
    ('20000000-0000-0000-0000-000000001015', '20000000-0000-0000-0000-000000000001', 16, '20000000-0000-0000-0000-000000000104', 'Ты слишком большой, теремок развалится.'),
    ('20000000-0000-0000-0000-000000001016', '20000000-0000-0000-0000-000000000001', 17, '20000000-0000-0000-0000-000000000105', 'Я тихонько, я с краю прилягу.'),
    ('20000000-0000-0000-0000-000000001017', '20000000-0000-0000-0000-000000000001', 18, '20000000-0000-0000-0000-000000000100', 'Полез медведь в теремок, и рассыпался теремок по брёвнышку.'),
    ('20000000-0000-0000-0000-000000001018', '20000000-0000-0000-0000-000000000001', 19, '20000000-0000-0000-0000-000000000101', 'Не беда, построим новый, побольше.'),
    ('20000000-0000-0000-0000-000000001019', '20000000-0000-0000-0000-000000000001', 20, '20000000-0000-0000-0000-000000000105', 'Я первым брёвна принесу, моя вина.'),
    ('20000000-0000-0000-0000-000000001020', '20000000-0000-0000-0000-000000000001', 21, '20000000-0000-0000-0000-000000000100', 'И построили они теремок лучше прежнего.');
INSERT INTO text_works (id, title, authors, language) VALUES
    ('30000000-0000-0000-0000-000000000001', 'Колобок', 'Русская народная сказка', 'rus');
INSERT INTO voice_parts (id, text_work_id, name) VALUES
    ('30000000-0000-0000-0000-000000000100', '30000000-0000-0000-0000-000000000001', 'Рассказчик'),
    ('30000000-0000-0000-0000-000000000101', '30000000-0000-0000-0000-000000000001', 'Старик'),
    ('30000000-0000-0000-0000-000000000102', '30000000-0000-0000-0000-000000000001', 'Старуха'),
    ('30000000-0000-0000-0000-000000000103', '30000000-0000-0000-0000-000000000001', 'Колобок'),
    ('30000000-0000-0000-0000-000000000104', '30000000-0000-0000-0000-000000000001', 'Заяц'),
    ('30000000-0000-0000-0000-000000000105', '30000000-0000-0000-0000-000000000001', 'Волк'),
    ('30000000-0000-0000-0000-000000000106', '30000000-0000-0000-0000-000000000001', 'Медведь'),
    ('30000000-0000-0000-0000-000000000107', '30000000-0000-0000-0000-000000000001', 'Лиса');
INSERT INTO text_work_fragments (id, text_work_id, number, voice_part_id, content) VALUES
    ('30000000-0000-0000-0000-000000001000', '30000000-0000-0000-0000-000000000001', 1, '30000000-0000-0000-0000-000000000100', 'Жили старик со старухой, и не было у них ни крошки хлеба.'),
    ('30000000-0000-0000-0000-000000001001', '30000000-0000-0000-0000-000000000001', 2, '30000000-0000-0000-0000-000000000101', 'Испеки, старуха, колобок, поскреби по сусекам.'),
    ('30000000-0000-0000-0000-000000001002', '30000000-0000-0000-0000-000000000001', 3, '30000000-0000-0000-0000-000000000102', 'Испеку, будет тебе колобок.'),
    ('30000000-0000-0000-0000-000000001003', '30000000-0000-0000-0000-000000000001', 4, '30000000-0000-0000-0000-000000000100', 'Испекла старуха колобок и положила на окошко студиться.'),
    ('30000000-0000-0000-0000-000000001004', '30000000-0000-0000-0000-000000000001', 5, '30000000-0000-0000-0000-000000000103', 'Полежал я, полежал, а теперь покачусь.'),
    ('30000000-0000-0000-0000-000000001005', '30000000-0000-0000-0000-000000000001', 6, '30000000-0000-0000-0000-000000000104', 'Колобок, колобок, я тебя съем!'),
    ('30000000-0000-0000-0000-000000001006', '30000000-0000-0000-0000-000000000001', 7, '30000000-0000-0000-0000-000000000103', 'Не ешь меня, я тебе песенку спою.'),
    ('30000000-0000-0000-0000-000000001007', '30000000-0000-0000-0000-000000000001', 8, '30000000-0000-0000-0000-000000000100', 'Спел колобок песенку и покатился дальше.'),
    ('30000000-0000-0000-0000-000000001008', '30000000-0000-0000-0000-000000000001', 9, '30000000-0000-0000-0000-000000000105', 'Колобок, колобок, я тебя съем!'),
    ('30000000-0000-0000-0000-000000001009', '30000000-0000-0000-0000-000000000001', 10, '30000000-0000-0000-0000-000000000103', 'Я от бабушки ушёл и от дедушки ушёл, и от тебя уйду.'),
    ('30000000-0000-0000-0000-000000001010', '30000000-0000-0000-0000-000000000001', 11, '30000000-0000-0000-0000-000000000106', 'Колобок, колобок, я тебя съем!'),
    ('30000000-0000-0000-0000-000000001011', '30000000-0000-0000-0000-000000000001', 12, '30000000-0000-0000-0000-000000000103', 'Где тебе, косолапому, меня догнать.'),
    ('30000000-0000-0000-0000-000000001012', '30000000-0000-0000-0000-000000000001', 13, '30000000-0000-0000-0000-000000000107', 'Какой ты румяный. Спой мне свою песенку.'),
    ('30000000-0000-0000-0000-000000001013', '30000000-0000-0000-0000-000000000001', 14, '30000000-0000-0000-0000-000000000103', 'Слушай, лиса, только не перебивай.'),
    ('30000000-0000-0000-0000-000000001014', '30000000-0000-0000-0000-000000000001', 15, '30000000-0000-0000-0000-000000000107', 'Стара я стала, сядь мне на носок и спой ещё разок.'),
    ('30000000-0000-0000-0000-000000001015', '30000000-0000-0000-0000-000000000001', 16, '30000000-0000-0000-0000-000000000100', 'Прыгнул колобок лисе на нос, тут она его и съела.'),
    ('30000000-0000-0000-0000-000000001016', '30000000-0000-0000-0000-000000000001', 17, '30000000-0000-0000-0000-000000000102', 'Говорила я, не клади его на окошко.'),
    ('30000000-0000-0000-0000-000000001017', '30000000-0000-0000-0000-000000000001', 18, '30000000-0000-0000-0000-000000000101', 'Испечём завтра новый, да съедим сами.');
